fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Requires that arr1 and arr2 have the same length and arr2 does not contain zero
    // Ensures that the result vector has the same length as arr1 and contains the element-wise division results
    // Invariant: The loop index i is always less than the length of arr1
    // Decreases: The length of arr1 minus i
    assert!(arr1.len() == arr2.len(), "Input arrays must have the same length");
    assert!(arr2.iter().all(|&x| x != 0), "Division by zero is not allowed");

    let mut result = Vec::with_capacity(arr1.len());
    
    // Loop invariant: 0 <= i <= arr1.len()
    for i in 0..arr1.len() {
        // Assert that we are within bounds
        assert!(i < arr1.len(), "Index out of bounds for arr1");
        assert!(i < arr2.len(), "Index out of bounds for arr2");
        
        // Perform integer division and push the result to the result vector
        result.push(arr1[i] / arr2[i]);
    }
    
    // Ensure that the result vector has the same length as arr1
    assert!(result.len() == arr1.len(), "Result vector must have the same length as arr1");
    
    // Return the resulting vector
    result
}